-- ปิดเดือน (2026-10-11) — ตาราง + trigger ล็อกเดือนที่ปิดแล้ว · รันซ้ำได้ (IF NOT EXISTS)
-- เดือนที่ status='CLOSED' แก้/เพิ่ม/ลบ รายการ บรรทัดย่อย และการตัดชำระ (ฝั่งรายการชำระ) ไม่ได้
CREATE TABLE IF NOT EXISTS LedgerPeriods (family_id TEXT NOT NULL, period TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'CLOSED', closed_by TEXT, closed_at TEXT, reopened_by TEXT, reopened_at TEXT, snapshot TEXT, PRIMARY KEY (family_id, period));
CREATE TABLE IF NOT EXISTS LedgerPeriodLog (log_id TEXT PRIMARY KEY, family_id TEXT NOT NULL, period TEXT NOT NULL, action TEXT NOT NULL, user_id TEXT, note TEXT, created_at TEXT);
CREATE INDEX IF NOT EXISTS idx_periodlog_family ON LedgerPeriodLog(family_id, created_at);
CREATE TRIGGER IF NOT EXISTS trg_period_tx_ins BEFORE INSERT ON Transactions FOR EACH ROW WHEN EXISTS (SELECT 1 FROM LedgerPeriods p JOIN Entities e ON e.family_id = p.family_id JOIN Accounts a ON a.entity_id = e.entity_id WHERE a.account_id = NEW.account_id AND p.period = substr(NEW.date, 1, 7) AND p.status = 'CLOSED') BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_tx_upd BEFORE UPDATE ON Transactions FOR EACH ROW WHEN EXISTS (SELECT 1 FROM LedgerPeriods p JOIN Entities e ON e.family_id = p.family_id JOIN Accounts a ON a.entity_id = e.entity_id WHERE a.account_id = OLD.account_id AND p.period = substr(OLD.date, 1, 7) AND p.status = 'CLOSED') OR EXISTS (SELECT 1 FROM LedgerPeriods p JOIN Entities e ON e.family_id = p.family_id JOIN Accounts a ON a.entity_id = e.entity_id WHERE a.account_id = NEW.account_id AND p.period = substr(NEW.date, 1, 7) AND p.status = 'CLOSED') BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_tx_del BEFORE DELETE ON Transactions FOR EACH ROW WHEN EXISTS (SELECT 1 FROM LedgerPeriods p JOIN Entities e ON e.family_id = p.family_id JOIN Accounts a ON a.entity_id = e.entity_id WHERE a.account_id = OLD.account_id AND p.period = substr(OLD.date, 1, 7) AND p.status = 'CLOSED') BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_td_ins BEFORE INSERT ON TransactionDetails FOR EACH ROW WHEN EXISTS (SELECT 1 FROM Transactions t JOIN Accounts a ON a.account_id = t.account_id JOIN Entities e ON e.entity_id = a.entity_id JOIN LedgerPeriods p ON p.family_id = e.family_id AND p.period = substr(t.date, 1, 7) AND p.status = 'CLOSED' WHERE t.transaction_id = NEW.transaction_id) BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_td_upd BEFORE UPDATE ON TransactionDetails FOR EACH ROW WHEN EXISTS (SELECT 1 FROM Transactions t JOIN Accounts a ON a.account_id = t.account_id JOIN Entities e ON e.entity_id = a.entity_id JOIN LedgerPeriods p ON p.family_id = e.family_id AND p.period = substr(t.date, 1, 7) AND p.status = 'CLOSED' WHERE t.transaction_id = OLD.transaction_id) OR EXISTS (SELECT 1 FROM Transactions t JOIN Accounts a ON a.account_id = t.account_id JOIN Entities e ON e.entity_id = a.entity_id JOIN LedgerPeriods p ON p.family_id = e.family_id AND p.period = substr(t.date, 1, 7) AND p.status = 'CLOSED' WHERE t.transaction_id = NEW.transaction_id) BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_td_del BEFORE DELETE ON TransactionDetails FOR EACH ROW WHEN EXISTS (SELECT 1 FROM Transactions t JOIN Accounts a ON a.account_id = t.account_id JOIN Entities e ON e.entity_id = a.entity_id JOIN LedgerPeriods p ON p.family_id = e.family_id AND p.period = substr(t.date, 1, 7) AND p.status = 'CLOSED' WHERE t.transaction_id = OLD.transaction_id) BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_st_ins BEFORE INSERT ON Settlements FOR EACH ROW WHEN EXISTS (SELECT 1 FROM TransactionDetails d JOIN Transactions t ON t.transaction_id = d.transaction_id JOIN Accounts a ON a.account_id = t.account_id JOIN Entities e ON e.entity_id = a.entity_id JOIN LedgerPeriods p ON p.family_id = e.family_id AND p.period = substr(t.date, 1, 7) AND p.status = 'CLOSED' WHERE d.detail_id = NEW.child_detail_id) BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
CREATE TRIGGER IF NOT EXISTS trg_period_st_del BEFORE DELETE ON Settlements FOR EACH ROW WHEN EXISTS (SELECT 1 FROM TransactionDetails d JOIN Transactions t ON t.transaction_id = d.transaction_id JOIN Accounts a ON a.account_id = t.account_id JOIN Entities e ON e.entity_id = a.entity_id JOIN LedgerPeriods p ON p.family_id = e.family_id AND p.period = substr(t.date, 1, 7) AND p.status = 'CLOSED' WHERE d.detail_id = OLD.child_detail_id) BEGIN SELECT RAISE(ABORT, 'PERIOD_CLOSED: เดือนนี้ปิดบัญชีแล้ว — ผู้ดูแลต้องเปิดเดือนก่อนจึงจะแก้ได้'); END;
